from ipaddress import ip_address, ip_network

# Configuration 1 from the WireGuard paper (keys shortened)
allowed = {
    "xTIB...p8Dg": ["10.192.122.3/32", "10.192.124.0/24"],
    "TrMv...WXX0": ["10.192.122.4/32", "192.168.0.0/16"],
    "gN65...z6EA": ["10.10.10.230/32"],
}

def peer_for(ip):                 # longest-prefix match over all peers
    best = None
    for peer, nets in allowed.items():
        for n in map(ip_network, nets):
            if ip_address(ip) in n and (not best or n.prefixlen > best[1]):
                best = (peer, n.prefixlen)
    return best[0] if best else None

# Sending: the destination address picks the peer (and its keys)
for dst in ["192.168.87.21", "10.10.10.230", "8.8.8.8"]:
    print(f"send to {dst:<14} encrypt for {peer_for(dst)}")

# Receiving: after decryption, the inner SOURCE must map back
# to the same peer whose keys decrypted the packet
def accept(decrypted_by, inner_src):
    return peer_for(inner_src) == decrypted_by

print(accept("TrMv...WXX0", "192.168.31.28"))   # paper's example
print(accept("TrMv...WXX0", "10.192.122.3"))    # claims xTIB's address

