# Toy SSH server message dispatcher (message numbers from RFC 4250-4254)
USERAUTH_REQUEST, CHANNEL_OPEN, CHANNEL_REQUEST = 50, 90, 98

class Session:
    def __init__(self):
        self.authenticated = False
        self.log = []

def handle_vulnerable(s, msg):
    # dispatches purely on the message number: no state check
    if msg == USERAUTH_REQUEST:
        s.log.append("try login")
    elif msg == CHANNEL_OPEN:
        s.log.append("open channel")
    elif msg == CHANNEL_REQUEST:
        s.log.append("RUN COMMAND")

def handle_fixed(s, msg):
    # RFC 4252 section 6: numbers 80 and up before auth is complete
    # are an error; the server MUST disconnect
    if msg >= 80 and not s.authenticated:
        s.log.append("disconnect: protocol error")
        raise ConnectionAbortedError
    handle_vulnerable(s, msg)

for name, handler in [("vulnerable", handle_vulnerable),
                      ("fixed", handle_fixed)]:
    s = Session()                     # attacker never logs in
    try:
        for m in [CHANNEL_OPEN, CHANNEL_REQUEST]:
            handler(s, m)
    except ConnectionAbortedError:
        pass
    print(f"{name:<10}", s.log)

