# RFC 3414 section 3.2 step 7a: is an authenticated SNMPv3 message
# fresh enough? (checked by the authoritative engine, e.g. a router)
MAX_BOOTS = 2147483647

def in_time_window(msg_boots, msg_time, local_boots, local_time):
    if local_boots == MAX_BOOTS:
        return False                     # engine must be reconfigured
    if msg_boots != local_boots:
        return False                     # sent before a reboot
    return abs(msg_time - local_time) <= 150

local_boots, local_time = 7, 86_400      # router: 7th boot, up 1 day
tests = {
    "fresh request":          (7, 86_390),
    "replayed 10 min later":  (7, 86_400 - 600),
    "captured before reboot": (6, 86_395),
}
for name, (b, t) in tests.items():
    ok = in_time_window(b, t, local_boots, local_time)
    print(f"{name:<24} {'accept' if ok else 'notInTimeWindow'}")
